using UnityEngine;
namespace HotelTogether {
 public sealed class HotelEconomyUI:MonoBehaviour {
  bool staffView;HotelEconomy economy;GUIStyle heading,body,button,small;Texture2D panel;void Awake(){economy=GetComponent<HotelEconomy>();}
  void Prepare(){if(heading!=null)return;heading=new GUIStyle(GUI.skin.label){font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf"),fontSize=25,fontStyle=FontStyle.Bold};body=new GUIStyle(GUI.skin.label){font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf"),fontSize=17,wordWrap=true};small=new GUIStyle(body){fontSize=13};button=new GUIStyle(GUI.skin.button){font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf"),fontSize=16,fontStyle=FontStyle.Bold};panel=new Texture2D(1,1);panel.SetPixel(0,0,new Color(.09f,.12f,.13f,.98f));panel.Apply();}
  void OnGUI(){if(!economy||!economy.Initialized)return;Prepare();var oldMatrix=GUI.matrix;var oldColor=GUI.color;float scale=Mathf.Clamp(Mathf.Min(Screen.width/1440f,Screen.height/900f),.1f,2);GUI.matrix=Matrix4x4.Scale(Vector3.one*scale);float width=Screen.width/scale,height=Screen.height/scale;
   if(economy.ModalOpen){GUI.color=Color.white;var r=new Rect((width-780)*.5f,(height-660)*.5f,780,660);GUI.DrawTexture(r,panel);GUI.color=new Color(.94f,.9f,.79f);if(economy.SummaryOpen)Report(r);else if(staffView)Roster(r);else Shop(r);}else if(economy.Hotel.Running){var rect=new Rect(24,98,260,157);GUI.DrawTexture(rect,panel);GUI.color=new Color(.94f,.9f,.79f);GUI.Label(new Rect(38,107,234,28),"WALLET  $"+economy.Wallet,body);GUI.Label(new Rect(38,137,234,24),"REPUTATION  "+Mathf.RoundToInt(economy.Reputation)+" / 100",small);var s=economy.Shift;GUI.Label(new Rect(38,163,234,67),"CHECK IN "+s.checkIns+" / "+economy.CheckInGoal+"    SERVICE "+s.services+" / "+economy.ServiceGoal+"\nCOLLECTED $"+s.Revenue+" / $"+economy.IncomeGoal+"\nU  HOTEL UPGRADES",small);}
   GUI.matrix=oldMatrix;GUI.color=oldColor;
  }
  void Report(Rect r){var s=economy.LastReport;if(s==null)return;GUI.Label(new Rect(r.x+30,r.y+25,720,40),"DAY "+s.day+"  /  SHIFT REPORT",heading);GUI.Label(new Rect(r.x+30,r.y+78,710,82),"Check-ins "+s.checkIns+"    Services "+s.services+"    Cleaning "+s.cleaning+"    Repairs "+s.repairs+"\nZombies stopped "+s.kills+"    Lives lost "+s.deaths+"    Rating "+Mathf.RoundToInt(s.rating)+" / 100",body);
   string[] rows={"Collected room payments|$"+s.rent,"Collected tips / work rewards|$"+s.tips,"Daily goal bonuses|+$"+s.bonus,"Utilities and upkeep|-$"+s.upkeep,"Staff wages|-$"+s.wages,"Guest compensation / misconduct|-$"+s.fines,"Upgrade purchases|-$"+s.investments,"SHIFT NET|$"+s.Net};for(int i=0;i<rows.Length;i++){var parts=rows[i].Split('|');GUI.Label(new Rect(r.x+30,r.y+182+i*35,510,30),parts[0],body);GUI.Label(new Rect(r.x+610,r.y+182+i*35,130,30),parts[1],body);}GUI.Label(new Rect(r.x+30,r.y+488,710,55),"Wallet $"+economy.Wallet+". Goals: check-ins "+s.checkInTarget+", services "+s.serviceTarget+", collect $"+s.incomeTarget+", rating 65+, protect every guest.",body);GUI.Label(new Rect(r.x+30,r.y+550,710,25),"Career money, reputation and upgrades saved at dawn.",small);if(GUI.Button(new Rect(r.x+30,r.y+591,720,44),"START DAY "+economy.Hotel.DayNumber,button))economy.ContinueDay();}
  void Roster(Rect r){GUI.Label(new Rect(r.x+30,r.y+25,720,40),"EMPLOYEE MANAGEMENT / "+economy.Staff.Count+" STAFF",heading);GUI.Label(new Rect(r.x+30,r.y+72,720,35),"Duty cycles on click. Assign specialists or ALL for automatic dispatch.",small);for(int i=0;i<economy.Staff.Count;i++){var worker=economy.Staff[i];float y=r.y+115+i*54;GUI.Label(new Rect(r.x+30,y,155,27),worker.StaffName,body);if(GUI.Button(new Rect(r.x+190,y,145,28),worker.OnDuty?"ON DUTY":"RESTING",button)){worker.SetOnDuty(!worker.OnDuty);economy.SaveStaffSettings();}if(GUI.Button(new Rect(r.x+345,y,145,28),worker.Duty.ToString(),button)){worker.SetDuty((StaffDuty)(((int)worker.Duty+1)%6));economy.SaveStaffSettings();}GUI.Label(new Rect(r.x+500,y,250,48),worker.State+" / "+worker.CompletedJobs+" jobs",small);}if(GUI.Button(new Rect(r.x+30,r.y+575,720,35),"BACK TO UPGRADES",button))staffView=false;if(GUI.Button(new Rect(r.x+30,r.y+616,720,30),"BACK TO WORK",button)){staffView=false;economy.CloseShop();}}
  void Shop(Rect r){GUI.Label(new Rect(r.x+30,r.y+25,720,40),"HOTEL MANAGEMENT  /  $"+economy.Wallet,heading);string[] names={"ROOM COMFORT","WORKSHOP EQUIPMENT","NIGHT SECURITY","HIRE EMPLOYEE"};string[] detail={"+$25 room rate per level; better tips and patience. Extra room cushion.","Repairs, mopping and washing +25% speed per level.","Openings +25% strength per level; +5 seconds night preparation.","2 starter employees included. Hire up to 6 more; $45/day per hired employee."};for(int i=0;i<4;i++){float y=r.y+88+i*104;GUI.Label(new Rect(r.x+30,y,505,28),names[i]+"   LEVEL "+economy.Levels[i]+" / "+(i==3?6:3),body);GUI.Label(new Rect(r.x+30,y+32,505,55),detail[i],small);bool max=economy.Levels[i]>=(i==3?6:3);int cost=economy.Price((HotelUpgrade)i);GUI.enabled=!max&&economy.Wallet>=cost;if(GUI.Button(new Rect(r.x+560,y+15,180,51),max?"MAX LEVEL":"BUY  $"+cost,button))economy.Purchase((HotelUpgrade)i);GUI.enabled=true;}GUI.Label(new Rect(r.x+30,r.y+524,710,40),"Collect cash from customers. Daily bills: $95 + staff wages. Upgrades and career balance save at the end of a shift.",small);if(GUI.Button(new Rect(r.x+30,r.y+563,710,32),"MANAGE EMPLOYEES ("+economy.Staff.Count+")",button))staffView=true;if(GUI.Button(new Rect(r.x+30,r.y+602,720,35),"BACK TO WORK",button))economy.CloseShop();}
  void OnDestroy(){if(panel)Destroy(panel);}
 }
}
